snippet_css:
:root{
  --bg: #FBF5E6;
  --fg: #4A3A2C;
  --muted: #6B4E37;
  --surface: #FFFDF7;
  --border: #E3CBA0;
  --accent: #A34A31;
  --accent-fg: #FFF6E8;
  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 12px 26px rgba(107,78,55,.16);
  --btn-shadow: 0 5px 0 rgba(163,74,49,.28);
  --art-bg: repeating-linear-gradient(90deg,rgba(163,74,49,.14) 0 12px,transparent 12px 24px),repeating-linear-gradient(0deg,rgba(106,138,90,.16) 0 12px,transparent 12px 24px);
  --media-bg: linear-gradient(180deg,#F3EAD3,#E3CBA0);
  --cta-bg: linear-gradient(180deg,#F5EEDC,#EBDFC4);
  --input-bg: #FFFDF7;
  --ok: #4E7A46;
  --warn: #A34A31;
  --font-display: Fraunces,'Noto Serif TC',serif;
  --font-body: Lora,'Noto Serif TC',serif;
  --font-mono: Fraunces,ui-serif,serif;
  --focus-ring: var(--accent);
}

